  const practice=[];
  const add=(level,code,prompt,answer,solution,marks=2,calculator='No calculator',command='Calculate',extra={})=>practice.push(Object.assign({id:`GSV6-1.3-${code}`,level,prompt,answer,solution,marks,calculator,command,hint:'',tags:['geometric sequences','finite geometric series']},extra));

  // Foundation · 24
  add('Foundation','F01','State the common ratio of \\(3,6,12,24,\\ldots\\).','\\(r=2\\).','Divide any term by the preceding term: \\(6/3=12/6=2\\).',1);
  add('Foundation','F02','State the common ratio of \\(81,27,9,3,\\ldots\\).','\\(r=\\frac13\\).','\\(27/81=9/27=1/3\\).',1);
  add('Foundation','F03','State the common ratio of \\(5,-10,20,-40,\\ldots\\).','\\(r=-2\\).','Each term is multiplied by \\(-2\\).',1);
  add('Foundation','F04','Which sequence is geometric?','\\(4,12,36,108,\\ldots\\).','Its consecutive ratios are all \\(3\\).',1,'No calculator','Identify',{choices:['\\(4,7,10,13,\\ldots\\)','\\(4,12,36,108,\\ldots\\)','\\(1,4,9,16,\\ldots\\)','\\(2,3,5,8,\\ldots\\)'],correct:1});
  add('Foundation','F05','For \\(7,14,28,56,\\ldots\\), write down \\(u_1\\) and \\(r\\).','\\(u_1=7,\\ r=2\\).','The first listed term is \\(7\\), and each term doubles.',2,'No calculator','Write down',{check:{mode:'text',accepted:['u1=7,r=2','7,2']}});
  add('Foundation','F06','Write the first five terms when \\(u_1=6\\) and \\(r=\\frac12\\).','\\(6,3,1.5,0.75,0.375\\).','Multiply repeatedly by \\(1/2\\).',2,'No calculator','Write down',{check:{mode:'text',accepted:['6,3,1.5,0.75,0.375','6 3 1.5 0.75 0.375']}});
  add('Foundation','F07','Find \\(u_8\\) when \\(u_1=5\\) and \\(r=2\\).','\\(u_8=640\\).','\\(u_8=5(2)^7=640\\).',2,'No calculator','Calculate',{check:{mode:'number',value:640,tolerance:1e-9}});
  add('Foundation','F08','Find \\(u_7\\) when \\(u_1=96\\) and \\(r=\\frac12\\).','\\(u_7=1.5\\).','\\(96(1/2)^6=96/64=1.5\\).',2,'No calculator','Calculate',{check:{mode:'number',value:1.5,tolerance:1e-9}});
  add('Foundation','F09','Find \\(u_6\\) when \\(u_1=3\\) and \\(r=-2\\).','\\(u_6=-96\\).','\\(u_6=3(-2)^5=-96\\).',2,'No calculator','Calculate',{check:{mode:'number',value:-96,tolerance:1e-9}});
  add('Foundation','F10','Write an explicit formula for \\(4,12,36,108,\\ldots\\).','\\(u_n=4(3)^{n-1}\\).','Use first term \\(4\\) and ratio \\(3\\).',2,'No calculator','Write',{check:{mode:'text',accepted:['u_n=4(3)^(n-1)','un=4*3^(n-1)','4(3)^{n-1}']}});
  add('Foundation','F11','Write a recursive rule for \\(80,60,45,33.75,\\ldots\\).','\\(u_1=80,\\ u_{n+1}=0.75u_n\\).','The ratio is \\(60/80=0.75\\).',2,'No calculator','Write',{check:{mode:'text',accepted:['u1=80,u(n+1)=0.75un','80,0.75']}});
  add('Foundation','F12','A quantity increases by \\(12\\%\\) each period. State its growth factor.','\\(1.12\\).','\\(1+12/100=1.12\\).',1,'No calculator','State',{check:{mode:'number',value:1.12,tolerance:1e-9}});
  add('Foundation','F13','A quantity decreases by \\(18\\%\\) each period. State its decay factor.','\\(0.82\\).','\\(1-18/100=0.82\\).',1,'No calculator','State',{check:{mode:'number',value:0.82,tolerance:1e-9}});
  add('Foundation','F14','Calculate \\(2+6+18+54\\).','\\(80\\).','Add the four terms or use \\(u_1=2,r=3,n=4\\).',2,'No calculator','Calculate',{check:{mode:'number',value:80,tolerance:1e-9}});
  add('Foundation','F15','Find \\(S_5\\) for \\(u_1=3\\) and \\(r=2\\).','\\(S_5=93\\).','\\(S_5=3(2^5-1)/(2-1)=93\\).',2,'No calculator','Calculate',{check:{mode:'number',value:93,tolerance:1e-9}});
  add('Foundation','F16','Find \\(S_4\\) for \\(64,32,16,8,\\ldots\\).','\\(S_4=120\\).','\\(64+32+16+8=120\\).',2,'No calculator','Calculate',{check:{mode:'number',value:120,tolerance:1e-9}});
  add('Foundation','F17','Find the sum of the first six terms when \\(u_1=5\\) and \\(r=-1\\).','\\(0\\).','The terms alternate \\(5,-5,5,-5,5,-5\\).',2,'No calculator','Calculate',{check:{mode:'number',value:0,tolerance:1e-9}});
  add('Foundation','F18','Find \\(n\\) if \\(u_n=486\\) in \\(2,6,18,54,\\ldots\\).','\\(n=6\\).','\\(2(3)^{n-1}=486=2(3^5)\\), so \\(n-1=5\\).',2,'No calculator','Find',{check:{mode:'number',value:6,tolerance:1e-9}});
  add('Foundation','F19','Does \\(100\\) occur in \\(4,12,36,108,\\ldots\\)?','No.','The target lies between \\(u_3=36\\) and \\(u_4=108\\), and the solved index is not an integer.',2,'No calculator','Determine',{choices:['Yes, at term 3.','Yes, at term 4.','No, because the required index is not an integer.','No, because the ratio is negative.'],correct:2});
  add('Foundation','F20','How many terms are in \\(\\displaystyle\\sum_{k=2}^{8}u_k\\)?','\\(7\\) terms.','\\(8-2+1=7\\).',1,'No calculator','State',{check:{mode:'number',value:7,tolerance:1e-9}});
  add('Foundation','F21','Expand \\(\\displaystyle\\sum_{k=0}^{3}5(2)^k\\).','\\(5+10+20+40\\).','Substitute \\(k=0,1,2,3\\).',2,'No calculator','Expand',{check:{mode:'text',accepted:['5+10+20+40','5,10,20,40']}});
  add('Foundation','F22','The positive numbers \\(3,x,48\\) are consecutive terms of a geometric sequence. Find \\(x\\).','\\(x=12\\).','\\(x^2=3(48)=144\\); positivity gives \\(x=12\\).',2,'No calculator','Find',{check:{mode:'number',value:12,tolerance:1e-9}});
  add('Foundation','F23','Interpret \\(r=0.94\\) in a repeated-change model.','The quantity decreases by \\(6\\%\\) per period.','\\(94\\%\\) remains, so \\(6\\%\\) is removed each step.',2,'No calculator','Interpret',{check:{mode:'text',accepted:['decreases by 6% per period','6% decrease each period','decays 6%']}});
  add('Foundation','F24','In a weekly-membership model, explain the difference between \\(u_{10}\\) and \\(S_{10}\\).','\\(u_{10}\\) is the week-10 value; \\(S_{10}\\) is the total from weeks 1 to 10.','A term is one stage; a partial sum accumulates all included stages.',2,'No calculator','Explain');

