  add('Application','A01','A programme has \\(80\\) new members in week \\(1\\) and grows by \\(18\\%\\) weekly. Find the week-12 prediction.','\\(u_{12}\\approx494.07\\).',`\\(u_{12}=80(1.18)^{11}\\approx${fmt(u12,2)}\\).`,2,'GDC allowed','Calculate',{check:{mode:'number',value:Number(u12.toFixed(2)),tolerance:0.02}});
  add('Application','A02','For the same model \\(u_1=80,r=1.18\\), find the total number predicted over the first \\(12\\) weeks.','\\(S_{12}\\approx2794.49\\).',`\\(S_{12}=80(1.18^{12}-1)/0.18\\approx${fmt(s12,2)}\\).`,3,'GDC allowed','Calculate',{check:{mode:'number',value:Number(s12.toFixed(2)),tolerance:0.02}});
  add('Application','A03','A medication amount is \\(1200\\) micrograms initially and retains \\(86\\%\\) each hour. Find the amount after \\(8\\) hours.','\\(359.06\\) micrograms.','Term \\(1\\) is hour \\(0\\), so after \\(8\\) hours use \\(1200(0.86)^8\\approx359.06\\).',3,'GDC allowed','Calculate',{check:{mode:'number',value:359.06,tolerance:0.02}});
  add('Application','A04','The first nine recorded medication amounts have \\(u_1=1200\\) and \\(r=0.86\\). Calculate their total.','\\(6365.76\\) micrograms.','\\(S_9=1200(1-0.86^9)/(1-0.86)\\approx6365.76\\).',3,'GDC allowed','Calculate',{check:{mode:'number',value:6365.76,tolerance:0.02}});
  add('Application','A05','A population begins at \\(2500\\) and grows by \\(35\\%\\) per period. Find the first term above \\(20000\\).','\\(n=8\\).','Solve \\(2500(1.35)^{n-1}>20000\\). Check \\(u_7\\approx15133.61\\) and \\(u_8\\approx20430.38\\).',4,'GDC allowed','Determine',{check:{mode:'number',value:8,tolerance:1e-9}});
  add('Application','A06','A network begins with \\(600\\) sensors and expands by a factor of \\(1.25\\) each phase. Find the first phase above \\(6000\\) sensors.','Phase \\(12\\).','\\(u_{11}\\approx5587.94\\) and \\(u_{12}\\approx6984.92\\), so phase \\(12\\) is first.',4,'GDC allowed','Determine',{check:{mode:'number',value:12,tolerance:1e-9}});
  add('Application','A07','A device value starts at \\(100\\) and retains \\(78\\%\\) each cycle. Find the first term below \\(10\\).','\\(n=11\\).','\\(u_{10}\\approx10.687\\) and \\(u_{11}\\approx8.336\\).',4,'GDC allowed','Determine',{check:{mode:'number',value:11,tolerance:1e-9}});
  add('Application','A08','A file process begins with \\(40\\) files and doubles each cycle. Find the total produced in the first \\(9\\) cycles.','\\(20440\\) files.','\\(S_9=40(2^9-1)=20440\\).',3,'GDC allowed','Calculate',{check:{mode:'number',value:20440,tolerance:1e-9}});
  add('Application','A09','A value is \\(500\\) at stage \\(1\\) and grows \\(22\\%\\) per stage. Find the first stage above \\(5000\\).','Stage \\(13\\).','\\(u_{12}\\approx4455.83\\), \\(u_{13}\\approx5436.11\\).',4,'GDC allowed','Determine',{check:{mode:'number',value:13,tolerance:1e-9}});
  add('Application','A10','A machine output begins at \\(200\\) units and falls by \\(15\\%\\) each cycle. Find the first cycle below \\(25\\) units.','Cycle \\(14\\).','Use \\(u_n=200(0.85)^{n-1}\\). Check \\(u_{13}\\approx28.448\\) and \\(u_{14}\\approx24.181\\).',4,'GDC allowed','Determine',{check:{mode:'number',value:14,tolerance:1e-9}});
  add('Application','A11','Given \\(u_2=12\\) and \\(u_5=324\\), find \\(u_1\\), \\(r\\), and \\(u_{10}\\).','\\(u_1=4,r=3,u_{10}=78732\\).','\\(r^3=324/12=27\\), so \\(r=3\\); then \\(u_1=4\\) and \\(u_{10}=4(3)^9\\).',5,'GDC allowed','Find',{check:{mode:'text',accepted:['4,3,78732','u1=4,r=3,u10=78732']}});
  add('Application','A12','Given \\(u_5=3\\) and \\(u_7=0.75\\), state all possible real values of \\(r\\).','\\(r=\\pm0.5\\).','\\(r^2=0.75/3=0.25\\), so both square roots are possible.',3,'GDC allowed','Find',{check:{mode:'text',accepted:['0.5,-0.5','±0.5','r=+-0.5','r=0.5 or -0.5']}});
  add('Application','A13','A geometric sequence has \\(u_3=20\\) and \\(u_6=160\\). Find \\(u_1\\) and \\(r\\).','\\(u_1=5,r=2\\).','\\(r^3=160/20=8\\), so \\(r=2\\). Then \\(u_1=20/2^2=5\\).',4,'GDC allowed','Find',{check:{mode:'text',accepted:['u1=5,r=2','5,2']}});
