  add('Application','A15','Calculate \\(2+4+8+\\cdots+1024\\).','\\(2046\\).','There are \\(10\\) terms; \\(S_{10}=2(2^{10}-1)=2046\\).',3,'GDC allowed','Calculate',{check:{mode:'number',value:2046,tolerance:1e-9}});
  add('Application','A16','Find the sum of the first \\(8\\) terms of \\(64,32,16,\\ldots\\).','\\(127.5\\).','\\(S_8=64[1-(1/2)^8]/(1/2)=127.5\\).',3,'GDC allowed','Calculate',{check:{mode:'number',value:127.5,tolerance:1e-9}});
  add('Application','A17','Calculate \\(12-6+3-1.5+0.75\\).','\\(8.25\\).','Use \\(u_1=12,r=-1/2,n=5\\) or add directly.',3,'GDC allowed','Calculate',{check:{mode:'number',value:8.25,tolerance:1e-9}});
  add('Application','A18','Evaluate \\(\\displaystyle\\sum_{k=3}^{8}2(3)^{k-1}\\).','\\(6552\\).','There are \\(6\\) terms, first \\(18\\), ratio \\(3\\): \\(18(3^6-1)/2=6552\\).',4,'GDC allowed','Calculate',{check:{mode:'number',value:6552,tolerance:1e-9}});
  add('Application','A19','For \\(u_1=4,r=2\\), calculate \\(u_5+u_6+\\cdots+u_{10}\\).','\\(4032\\).','The block has first term \\(64\\), six terms and ratio \\(2\\): \\(64(2^6-1)=4032\\).',4,'GDC allowed','Calculate',{check:{mode:'number',value:4032,tolerance:1e-9}});
